<script setup lang="ts">
import {ref,reactive,computed,onMounted,onUnmounted,watch} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {User,Search,Plus,Upload,Setting,ArrowRight,ArrowDown,Download,SwitchButton,Calendar,Connection,Check,Refresh,Document,Lock,Promotion,EditPen,DataAnalysis} from '@element-plus/icons-vue';
import CardPreview from './CardPreview.vue';
import {api,post,patch,upload,download,savePdf,desktopInvoke,type Member,type Card,type Store,type ImportBatch,type BackupSettings,type BackupJob,type MonthlyReport,mainCard,kindLabel,statusLabels,day,addDays,formatDateTime,formatDate} from './api';
const ready=ref(false),authenticated=ref(false),password=ref(''),loginBusy=ref(false),tab=ref('members');
const store=reactive<Store>({name:'悦体健身',phone:'',monthCardDays:30,yearCardDays:365,hasLogo:true});
const storeDraft=reactive({name:'',phone:'',monthCardDays:30,yearCardDays:365}),logoVersion=ref(0),settingsBusy=ref(false);
const stats=reactive({total:0,active:0,expiring:0,expired:0});
const setupRequired=ref(false),setupBusy=ref(false),setupForm=reactive({name:'悦体健身',phone:'',monthCardDays:30,yearCardDays:365,password:'',confirm:'',backupDirectory:'',senderEmail:'',recipientEmail:'',smtpCode:''});
const list=ref<Member[]>([]),total=ref(0),loading=ref(false),page=ref(1),search=ref(''),status=ref(''),endRange=ref<string[]>([]),expiringOnly=ref(false);
const drawer=ref(false),selected=ref<Member|null>(null),detailTab=ref('cards'),detailLoading=ref(false);
const memberDialog=ref(false),editingMember=ref(false),saving=ref(false);
const memberForm=reactive({name:'',phone:'',note:'',cardRemark:'',kind:'year',startDate:day(),endDate:addDays(day(),365)});
const cardDialog=ref(false),cardEditing=ref<Card|null>(null),cardForm=reactive({kind:'year',startDate:day(),endDate:'',remark:''});
const renewalUnexpired=ref(false),renewalOriginalEnd=ref('');
const expandedRemarks=ref<Set<string>>(new Set());
const importing=ref(false),preview=ref<ImportBatch|null>(null),batches=ref<any[]>([]),fileInput=ref<HTMLInputElement>(),logoInput=ref<HTMLInputElement>();
const passwordForm=reactive({current:'',next:'',confirm:''});
const backup=reactive<BackupSettings>({directory:'',senderEmail:'',recipientEmail:'',scheduleTime:'13:00',retentionCount:30,latest:null,automaticStatus:'waiting',automaticStatusText:'等待设定时间',today:day(),latestAutomaticDate:null,initializedDate:null});
const backupDraft=reactive({directory:'',senderEmail:'',recipientEmail:'',scheduleTime:'13:00',retentionCount:30,smtpCode:''});
const backupJobs=ref<BackupJob[]>([]),backupBusy=ref(false),restoreInput=ref<HTMLInputElement>();
const reportMonth=ref(day().slice(0,7)),report=ref<MonthlyReport|null>(null),reportLoading=ref(false),reportSaving=ref(false);
const headings:Record<string,{title:string;subtitle:string}>={members:{title:'会员管理',subtitle:'每一份坚持，都值得被认真记录。'},reports:{title:'统计报表',subtitle:'用会员变化和续卡情况，看清门店经营节奏。'},imports:{title:'批量导入',subtitle:'用Excel快速建立会员档案。'},settings:{title:'系统设置',subtitle:'设置门店、会员卡期限与每日备份。'}};
const heading=computed(()=>headings[tab.value]);
const todayText=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
const historyLabels:Record<string,string>={opened:'首次开卡',renewed:'续卡',updated:'修改卡片',voided:'作废卡片',migrated:'历史卡片'};
const activeRate=computed(()=>stats.total?Math.round(stats.active/stats.total*100):0);
const expireHint=(card?:Card)=>{if(!card||card.status!=='active')return '';const n=Math.round((Date.parse(card.end_date)-Date.parse(day()))/86400000),limit=card.kind==='month'?7:30;return n<=limit?(n===0?'今天到期':`${n} 天后到期`):'';};
const hasFilters=computed(()=>!!(search.value||status.value||endRange.value?.length||expiringOnly.value));
const effectiveRenewalKind=computed(()=>renewalUnexpired.value&&selected.value?.card?.kind==='year'?'year':cardForm.kind);
const durationDays=(kind:string)=>kind==='year'?store.yearCardDays:store.monthCardDays;
const memberRemarkRequired=computed(()=>!!memberForm.startDate&&!!memberForm.endDate&&memberForm.endDate!==addDays(memberForm.startDate,durationDays(memberForm.kind)));
const cardRemarkRequired=computed(()=>{
  if(!cardForm.startDate||!cardForm.endDate)return false;
  if(cardEditing.value)return cardForm.startDate!==cardEditing.value.start_date||cardForm.endDate!==cardEditing.value.end_date;
  const base=renewalUnexpired.value?renewalOriginalEnd.value:cardForm.startDate;
  return !!base&&cardForm.endDate!==addDays(base,durationDays(cardForm.kind));
});
const historyTitle=(event:Member['cardHistory'][number])=>event.event_type==='renewed'?`续${kindLabel(event.selected_kind||event.kind)}`:(historyLabels[event.event_type]||'会员卡记录');
const remarkLong=(value:string)=>value.length>80||value.split(/\r?\n/).length>2;
const remarkExpanded=(id:string)=>expandedRemarks.value.has(id);
function toggleRemark(id:string){const next=new Set(expandedRemarks.value);next.has(id)?next.delete(id):next.add(id);expandedRemarks.value=next;}
const initials=(name:string)=>name.slice(-2);
async function run(fn:()=>Promise<void>){try{await fn();}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:typeof e==='string'?e:'操作未完成，请重试');}}
async function loadStore(){Object.assign(store,await api<Store>('/store'));Object.assign(storeDraft,{name:store.name,phone:store.phone,monthCardDays:store.monthCardDays,yearCardDays:store.yearCardDays});}
async function completeSetup(){if(setupForm.password.length<8)throw new Error('管理员密码至少 8 位');if(setupForm.password!==setupForm.confirm)throw new Error('两次输入的管理员密码不一致');setupBusy.value=true;try{await post('/setup',{name:setupForm.name,phone:setupForm.phone,monthCardDays:setupForm.monthCardDays,yearCardDays:setupForm.yearCardDays,password:setupForm.password,backupDirectory:setupForm.backupDirectory,senderEmail:setupForm.senderEmail,recipientEmail:setupForm.recipientEmail||setupForm.senderEmail});let credentialError='';if(setupForm.smtpCode&&setupForm.senderEmail){try{await desktopInvoke('save_smtp_credential',{senderEmail:setupForm.senderEmail,authorizationCode:setupForm.smtpCode});}catch(e:any){credentialError=e instanceof Error?e.message:String(e);}}setupRequired.value=false;password.value=setupForm.password;await login();ElMessage.success('悦体健身单机版初始化完成');if(credentialError)ElMessage.warning(`SMTP授权码暂未保存：${credentialError}`);}finally{setupBusy.value=false;}}
let listRequest=0;
async function loadList(){const seq=++listRequest;loading.value=true;try{const query=new URLSearchParams({page:String(page.value),pageSize:'8'});if(search.value)query.set('search',search.value);if(status.value)query.set('status',status.value);if(endRange.value?.[0]){query.set('endFrom',endRange.value[0]);query.set('endTo',endRange.value[1]);}if(expiringOnly.value)query.set('expiring','true');const result=await api<{items:Member[];total:number}>(`/admin/members?${query}`);if(seq===listRequest){list.value=result.items;total.value=result.total;}}finally{if(seq===listRequest)loading.value=false;}}
async function refresh(){await Promise.all([loadList(),api('/admin/stats').then(data=>Object.assign(stats,data))]);}
async function login(){loginBusy.value=true;try{await post('/admin/login',{password:password.value});password.value='';authenticated.value=true;await refresh();}finally{loginBusy.value=false;}}
async function logout(){await post('/admin/logout');authenticated.value=false;drawer.value=false;selected.value=null;list.value=[];preview.value=null;}
function expired(){authenticated.value=false;drawer.value=false;selected.value=null;list.value=[];preview.value=null;}
async function switchTab(value:string){tab.value=value;if(value==='members')await refresh();if(value==='reports')await loadReport();if(value==='imports')batches.value=await api('/admin/imports');if(value==='settings'){await Promise.all([loadStore(),loadBackup()]);}}
let searchTimer:ReturnType<typeof setTimeout>;
function filter(){expiringOnly.value=false;page.value=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>run(loadList),250);}
async function showExpiring(){clearTimeout(searchTimer);endRange.value=[];search.value='';status.value='';expiringOnly.value=true;page.value=1;await loadList();}
async function clearFilters(){clearTimeout(searchTimer);search.value='';status.value='';endRange.value=[];expiringOnly.value=false;page.value=1;await loadList();}
async function openMember(member:Member){drawer.value=true;detailLoading.value=true;detailTab.value='cards';expandedRemarks.value=new Set();try{selected.value=await api(`/admin/members/${member.id}`);}finally{detailLoading.value=false;}}
async function reloadSelected(){if(selected.value)selected.value=await api(`/admin/members/${selected.value.id}`);await refresh();}
function newMember(){editingMember.value=false;const startDate=day();Object.assign(memberForm,{name:'',phone:'',note:'',cardRemark:'',kind:'year',startDate,endDate:addDays(startDate,store.yearCardDays)});memberDialog.value=true;}
function editMember(){if(!selected.value)return;editingMember.value=true;Object.assign(memberForm,{name:selected.value.name,phone:selected.value.phone,note:selected.value.note});memberDialog.value=true;}
async function saveMember(){
  if(!memberForm.name.trim()||!/^1[3-9]\d{9}$/.test(memberForm.phone))throw new Error('请填写姓名及正确的 11 位手机号');
  if(!editingMember.value&&(!memberForm.startDate||!memberForm.endDate))throw new Error('请指定完整的有效期间');
  if(!editingMember.value&&memberRemarkRequired.value&&!memberForm.cardRemark.trim())throw new Error(`期限不是月卡 ${store.monthCardDays} 天或年卡 ${store.yearCardDays} 天，请填写备注`);
  saving.value=true;try{
    if(editingMember.value&&selected.value){await patch(`/admin/members/${selected.value.id}`,{name:memberForm.name,phone:memberForm.phone,note:memberForm.note,version:selected.value.version});await reloadSelected();}
    else{await post('/admin/members',{...memberForm});page.value=1;await refresh();}
    memberDialog.value=false;ElMessage.success(editingMember.value?'会员资料已更新':'会员已录入，可扫码领取会员卡');
  }finally{saving.value=false;}
}
function renew(card?:Card){
  if(!selected.value?.card)return;
  cardEditing.value=card||null;
  if(card){renewalUnexpired.value=false;renewalOriginalEnd.value='';Object.assign(cardForm,{kind:card.kind,startDate:card.start_date,endDate:card.end_date,remark:''});}
  else{const current=selected.value.card,today=day();renewalUnexpired.value=!current.voided_at&&current.end_date>=today;renewalOriginalEnd.value=renewalUnexpired.value?current.end_date:'';const startDate=renewalUnexpired.value?current.start_date:today,baseDate=renewalUnexpired.value?current.end_date:startDate;Object.assign(cardForm,{kind:current.kind,startDate,endDate:addDays(baseDate,durationDays(current.kind)),remark:''});}
  cardDialog.value=true;
}
async function saveCard(){if(!selected.value?.card)return;if(!cardForm.startDate||!cardForm.endDate)throw new Error('请指定完整的有效期间');if(cardRemarkRequired.value&&!cardForm.remark.trim())throw new Error(cardEditing.value?'修改会员卡日期时必须填写备注':`续卡期限不是月卡 ${store.monthCardDays} 天或年卡 ${store.yearCardDays} 天，请填写备注`);saving.value=true;try{const base=`/admin/members/${selected.value.id}/card`;if(cardEditing.value)await patch(base,{...cardForm,version:selected.value.card.version});else await post(`${base}/renew`,{...cardForm,version:selected.value.card.version});cardDialog.value=false;await reloadSelected();ElMessage.success(cardEditing.value?'会员卡已修改':'续卡已完成');}finally{saving.value=false;}}
async function voidCard(){if(!selected.value?.card)return;const result=await ElMessageBox.prompt(`即将作废 ${selected.value.name}（${selected.value.card_number}）的会员卡。作废后历史记录会保留，请填写原因。`,'确认作废会员卡',{inputPlaceholder:'例如：录入错误，重新开卡',inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'确认作废',confirmButtonClass:'void-confirm-button',cancelButtonText:'取消',type:'warning'});await post(`/admin/members/${selected.value.id}/card/void`,{reason:result.value});await reloadSelected();ElMessage.success('会员卡已作废');}
async function loadReport(){reportLoading.value=true;try{report.value=await api<MonthlyReport>(`/admin/reports/monthly?month=${reportMonth.value}`);}finally{reportLoading.value=false;}}
async function exportPdf(type:'members'|'monthly'){
  reportSaving.value=true;try{const monthly=type==='monthly',suffix=monthly?reportMonth.value:day().replaceAll('-','');const path=monthly?`/admin/reports/monthly.pdf?month=${reportMonth.value}`:'/admin/reports/members.pdf';const name=monthly?`悦体健身月度经营报表-${suffix}.pdf`:`悦体健身全部会员名单-${suffix}.pdf`;const saved=await savePdf(path,name);if(saved)ElMessage.success('PDF报表已保存');}finally{reportSaving.value=false;}
}
async function resetBinding(){if(!selected.value)return;const result=await ElMessageBox.prompt('请先核实会员本人身份。重置后，旧微信将立即失去访问权限。','重置微信绑定',{inputPlaceholder:'填写重置原因',inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'已核实，重置绑定',cancelButtonText:'取消',type:'warning'});await post(`/admin/members/${selected.value.id}/reset-binding`,{reason:result.value});await reloadSelected();ElMessage.success('绑定已重置，请会员重新扫码');}
async function chooseImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;input.value='';if(!file.name.toLowerCase().endsWith('.xlsx')||file.size>5*1024*1024)throw new Error('请选择不超过 5 MB 的 .xlsx 文件');importing.value=true;preview.value=null;try{preview.value=await upload('/admin/imports/preview',file);batches.value=await api('/admin/imports');}finally{importing.value=false;}}
async function confirmImport(){if(!preview.value)return;await ElMessageBox.confirm(`将新增 ${preview.value.count} 位会员及其会员卡，请确认预览信息无误。`,'确认导入',{confirmButtonText:'确认导入',cancelButtonText:'返回检查'});importing.value=true;try{preview.value=await post(`/admin/imports/${preview.value.id}/confirm`);batches.value=await api('/admin/imports');await refresh();ElMessage.success('全部会员导入成功');}finally{importing.value=false;}}
async function saveSettings(){settingsBusy.value=true;try{await patch('/admin/settings',storeDraft);await loadStore();ElMessage.success('门店及会员卡期限设置已保存，仅影响之后的新办和续卡');}finally{settingsBusy.value=false;}}
async function chooseLogo(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;input.value='';await upload('/admin/settings/logo',file);logoVersion.value++;await loadStore();ElMessage.success('门店 Logo 已更新');}
async function changePassword(){if(passwordForm.next!==passwordForm.confirm)throw new Error('两次输入的新密码不一致');if(passwordForm.next.length<8)throw new Error('新密码至少 8 位');await post('/admin/password',{current:passwordForm.current,next:passwordForm.next});Object.assign(passwordForm,{current:'',next:'',confirm:''});authenticated.value=false;ElMessage.success('密码已更新，请重新登录');}
async function loadBackup(){const data=await api<BackupSettings>('/admin/backup/settings');Object.assign(backup,data);Object.assign(backupDraft,{directory:data.directory,senderEmail:data.senderEmail,recipientEmail:data.recipientEmail,scheduleTime:data.scheduleTime,retentionCount:data.retentionCount,smtpCode:''});backupJobs.value=await api('/admin/backup/jobs');}
async function chooseBackupDirectory(){backupDraft.directory=await desktopInvoke<string>('choose_backup_directory',{current:backupDraft.directory});}
async function saveBackupSettings(){backupBusy.value=true;try{const data=await patch<BackupSettings>('/admin/backup/settings',{directory:backupDraft.directory,senderEmail:backupDraft.senderEmail,recipientEmail:backupDraft.recipientEmail||backupDraft.senderEmail,scheduleTime:backupDraft.scheduleTime,retentionCount:backupDraft.retentionCount});if(backupDraft.smtpCode)await desktopInvoke('save_smtp_credential',{senderEmail:backupDraft.senderEmail,authorizationCode:backupDraft.smtpCode});Object.assign(backup,data);Object.assign(backupDraft,{recipientEmail:data.recipientEmail,smtpCode:''});ElMessage.success('自动备份设置已保存');}finally{backupBusy.value=false;}}
async function testBackupEmail(){backupBusy.value=true;try{await saveBackupSettings();await desktopInvoke('test_backup_email');ElMessage.success('测试邮件已发送，请检查收件箱');}finally{backupBusy.value=false;}}
async function runBackup(){backupBusy.value=true;try{await saveBackupSettings();try{await desktopInvoke('run_backup',{force:true});}catch(e:any){if(String(e?.message||e).includes('桌面程序'))await post('/admin/backup/run');else throw e;}await loadBackup();ElMessage.success('完整备份已保存并提交邮件发送');}finally{backupBusy.value=false;}}
async function openBackupDirectory(){await desktopInvoke('open_backup_directory');}
async function openOperationLogDirectory(){await desktopInvoke('open_operation_log_directory');}
async function restoreBackup(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;input.value='';await ElMessageBox.confirm('恢复将用备份中的会员数据替换当前数据。系统会先自动保存当前数据，确认继续吗？','恢复完整备份',{type:'warning',confirmButtonText:'确认恢复',cancelButtonText:'取消'});backupBusy.value=true;try{const result=await upload<{members:number}>('/admin/backup/restore',file);await Promise.all([refresh(),loadStore(),loadBackup()]);ElMessage.success(`恢复完成，共 ${result.members} 位会员`);}finally{backupBusy.value=false;}}
watch([()=>memberForm.kind,()=>memberForm.startDate],()=>{if(memberDialog.value&&!editingMember.value&&memberForm.startDate)memberForm.endDate=addDays(memberForm.startDate,durationDays(memberForm.kind));});
watch([()=>cardForm.kind,()=>cardForm.startDate],()=>{if(!cardDialog.value||cardEditing.value||!selected.value?.card)return;const base=renewalUnexpired.value?renewalOriginalEnd.value:cardForm.startDate;if(base)cardForm.endDate=addDays(base,durationDays(cardForm.kind));});
onMounted(async()=>{window.addEventListener('auth-expired',expired);try{const setup=await api<{required:boolean}>('/setup/status');setupRequired.value=setup.required;await loadStore();if(!setup.required){try{await api('/admin/session');authenticated.value=true;await refresh();}catch{}}}finally{ready.value=true;}});
onUnmounted(()=>{window.removeEventListener('auth-expired',expired);clearTimeout(searchTimer);});
</script>

<template>
  <div v-if="!ready" class="boot"><img class="brand-mark" src="/brand/joyfit-mark.png" alt="悦体健身"/><p>正在连接悦体健身…</p></div>
  <div v-else-if="setupRequired" class="setup-layout">
    <section class="setup-card"><div class="setup-brand"><img src="/brand/joyfit-logo.png" alt="悦体健身 JOYFIT"/><div><span class="eyebrow green">FIRST RUN</span><h1>首次设置</h1><p>设置只需完成一次，之后直接使用管理员密码登录。</p></div></div>
      <el-form label-position="top" @submit.prevent><h2>门店与会员卡</h2><div class="form-grid"><el-form-item label="门店名称"><el-input v-model="setupForm.name" maxlength="50"/></el-form-item><el-form-item label="联系电话"><el-input v-model="setupForm.phone" maxlength="30"/></el-form-item><el-form-item label="月卡有效天数"><el-input-number v-model="setupForm.monthCardDays" :min="1" :max="3650"/></el-form-item><el-form-item label="年卡有效天数"><el-input-number v-model="setupForm.yearCardDays" :min="1" :max="3650"/></el-form-item></div><h2>管理员密码</h2><div class="form-grid"><el-form-item label="管理员密码"><el-input v-model="setupForm.password" type="password" show-password placeholder="至少8位，可使用纯数字"/></el-form-item><el-form-item label="再次输入"><el-input v-model="setupForm.confirm" type="password" show-password/></el-form-item></div><h2>自动备份（可稍后设置）</h2><el-form-item label="本地备份目录"><el-input v-model="setupForm.backupDirectory" placeholder="留空使用“文档\悦体健身\自动备份”"/></el-form-item><div class="form-grid"><el-form-item label="QQ发件邮箱"><el-input v-model="setupForm.senderEmail" placeholder="example@qq.com"/></el-form-item><el-form-item label="备份收件邮箱"><el-input v-model="setupForm.recipientEmail" placeholder="可与发件邮箱相同"/></el-form-item></div><el-form-item label="QQ邮箱SMTP授权码"><el-input v-model="setupForm.smtpCode" type="password" show-password placeholder="不是QQ登录密码"/></el-form-item></el-form><el-button type="primary" size="large" :loading="setupBusy" @click="run(completeSetup)">完成设置并进入系统</el-button></section>
  </div>
  <div v-else-if="!authenticated" class="login-layout">
    <section class="login-art"><div class="brand-lockup"><img class="brand-logo" src="/brand/joyfit-logo.png" alt="悦体健身 JOYFIT"/><span>会员管理工作台</span></div><div class="login-copy"><span class="eyebrow">BUILT FOR YOUR COMMUNITY</span><h1>每一次坚持，<br>都有归属。</h1><p>从一张会员卡开始，<br>把更多精力留给会员和运动本身。</p><div class="login-card-sample"><div>JOYFIT MEMBER <img src="/brand/joyfit-mark.png" alt=""/></div><h2>年卡 <small>ANNUAL PASS</small></h2><p>YOUR EVERYDAY, STRONGER.</p></div></div><span class="login-foot">一个门店 · 一份专注</span></section>
    <section class="login-panel"><div class="login-box"><span class="eyebrow green">WELCOME BACK</span><h2>欢迎回到悦体健身</h2><p class="muted">{{store.name}} · JOYFIT</p><form @submit.prevent="run(login)"><label for="owner-password">管理员密码</label><el-input id="owner-password" v-model="password" size="large" type="password" show-password autocomplete="current-password" placeholder="输入你的管理员密码" :prefix-icon="Lock"/><el-button type="primary" size="large" native-type="submit" :loading="loginBusy" class="login-submit">进入工作台 <el-icon><ArrowRight/></el-icon></el-button></form><div class="login-note"><el-icon><Lock/></el-icon><span>本程序的数据保存在当前电脑，仅供门店管理员使用。</span></div></div><span class="panel-footer">JOYFIT / 悦体健身会员管理</span></section>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="brand-lockup sidebar-brand"><img class="brand-logo" src="/brand/joyfit-logo.png" alt="悦体健身 JOYFIT"/><img class="brand-mark" src="/brand/joyfit-mark.png" alt="悦体健身"/><span>单机管理工作台</span></div><div class="nav-label">工作空间</div><nav><button :class="{active:tab==='members'}" @click="run(()=>switchTab('members'))"><el-icon><User/></el-icon>会员管理</button><button :class="{active:tab==='reports'}" @click="run(()=>switchTab('reports'))"><el-icon><DataAnalysis/></el-icon>统计报表</button><button :class="{active:tab==='imports'}" @click="run(()=>switchTab('imports'))"><el-icon><Upload/></el-icon>批量导入</button><button :class="{active:tab==='settings'}" @click="run(()=>switchTab('settings'))"><el-icon><Setting/></el-icon>系统设置</button></nav><div class="sidebar-help"><div class="help-icon"><img src="/brand/joyfit-mark.png" alt=""/></div><b>本地数据更轻便</b><p>会员资料保存在本机，<br>每天通过Excel自动备份。</p><button @click="run(()=>switchTab('settings'))">检查备份设置 <el-icon><ArrowRight/></el-icon></button></div><div class="sidebar-owner"><div><b>悦体健身管理员</b><span>管理员账号</span></div><button title="退出登录" aria-label="退出登录" @click="run(logout)"><el-icon><SwitchButton/></el-icon></button></div></aside>
    <div class="workspace"><header class="topbar"><div class="breadcrumb">工作空间 <span>/</span> <b>{{heading.title}}</b></div><div class="store-chip"><span class="live-dot"></span>{{store.name}}<span class="single-store">杭宁府店</span></div></header>
    <main><div class="page-heading"><div><span class="eyebrow green">{{tab==='members'?'YOUR MEMBERS, AT A GLANCE':tab==='reports'?'KNOW YOUR BUSINESS':tab==='imports'?'A FRESH START, TOGETHER':'MAKE IT YOURS'}}</span><h1>{{heading.title}}</h1><p>{{heading.subtitle}}</p></div><div v-if="tab==='members'" class="heading-actions"><el-button :icon="DataAnalysis" :loading="reportSaving" @click="run(()=>exportPdf('members'))">导出全部会员 PDF</el-button><el-button type="primary" :icon="Plus" @click="newMember">新增会员</el-button></div></div>
    <template v-if="tab==='members'">
      <section class="metrics"><div class="metric"><div class="metric-label">全部会员<el-icon><User/></el-icon></div><div class="metric-value">{{stats.total.toLocaleString()}}<span>位</span></div><div class="metric-foot"><span class="dot dark"></span>你的运动社群</div></div><div class="metric"><div class="metric-label">有效会员<el-icon><Check/></el-icon></div><div class="metric-value">{{stats.active.toLocaleString()}}<span>位</span></div><div class="metric-foot"><span class="metric-percent">{{activeRate}}%</span>占全部会员</div></div><div class="metric"><div class="metric-label">即将到期<el-icon><Calendar/></el-icon></div><div class="metric-value amber">{{stats.expiring.toLocaleString()}}<span>位</span></div><button class="metric-link" @click="run(showExpiring)">及时关注续卡 <span>↗</span></button><div class="metric-foot">年卡 30 天 · 月卡 7 天</div></div><div class="metric"><div class="metric-label">已到期<el-icon><Calendar/></el-icon></div><div class="metric-value">{{stats.expired.toLocaleString()}}<span>位</span></div><div class="metric-foot">可在会员详情中重新续卡</div></div></section>
      <section class="members-panel"><div class="panel-heading"><div><h2>会员档案 <span>{{total}}</span></h2><p>资料、卡片与有效期，一处管理</p></div><span class="date-note"><el-icon><Calendar/></el-icon>{{todayText}}</span></div><div class="filters"><el-input v-model="search" placeholder="搜索姓名、手机号或会员号码" :prefix-icon="Search" clearable class="search-input" @input="filter"/><el-select v-model="status" placeholder="全部状态" clearable @change="filter"><el-option v-for="(label,value) in statusLabels" :key="value" :label="label" :value="value"/></el-select><el-date-picker v-model="endRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="到期日期" end-placeholder="结束日期" range-separator="至" @change="filter"/><el-button v-if="hasFilters" @click="run(clearFilters)">查看全部会员</el-button><el-button :icon="Refresh" title="刷新列表" aria-label="刷新列表" @click="run(refresh)"/></div><div v-if="expiringOnly" class="filter-notice"><span>当前筛选：即将到期（年卡 30 天、月卡 7 天）</span><button @click="run(clearFilters)">清除筛选</button></div>
      <el-table :data="list" v-loading="loading" row-key="id" @row-click="(row:Member)=>run(()=>openMember(row))" class="members-table"><el-table-column label="会员" min-width="190"><template #default="{row}"><div class="member-identity"><div><b>{{row.name}}</b><span>{{row.card_number}}</span></div></div></template></el-table-column><el-table-column prop="phone" label="手机号" min-width="137"/><el-table-column label="会员卡" width="100"><template #default="{row}"><span class="kind-badge" :class="mainCard(row)?.kind">{{mainCard(row)?kindLabel(mainCard(row)!.kind):'—'}}</span></template></el-table-column><el-table-column label="有效期间" min-width="210"><template #default="{row}"><div class="date-cell">{{mainCard(row)?formatDate(mainCard(row)!.start_date):'—'}} <span>至</span> {{mainCard(row)?formatDate(mainCard(row)!.end_date):'—'}}<small v-if="expireHint(mainCard(row))">{{expireHint(mainCard(row))}}</small></div></template></el-table-column><el-table-column label="状态" width="115"><template #default="{row}"><span class="status-pill member-status" :class="mainCard(row)?.status"><i></i>{{statusLabels[mainCard(row)?.status||'']||'—'}}</span></template></el-table-column><el-table-column label="" width="60" align="right"><template #default="{row}"><button class="row-arrow" :aria-label="'查看'+row.name" @click.stop="run(()=>openMember(row))"><el-icon><ArrowRight/></el-icon></button></template></el-table-column><template #empty><div class="empty-state"><div class="empty-icon"><el-icon><User/></el-icon></div><b>{{hasFilters?'没有找到匹配的会员':'从第一位会员开始'}}</b><p>{{hasFilters?'试试调整搜索条件或筛选范围。':'录入会员资料，或通过 Excel 一次导入。'}}</p><el-button v-if="hasFilters" type="primary" plain @click="run(clearFilters)">查看全部会员</el-button><el-button v-else type="primary" plain @click="newMember">新增会员</el-button></div></template></el-table>
      <div class="table-footer"><span>共 {{total}} 位会员 · 每页 8 位</span><el-pagination v-model:current-page="page" :page-size="8" :total="total" layout="prev, pager, next" @current-change="run(loadList)"/></div></section>
      <div class="bottom-note"><el-icon><Lock/></el-icon>会员资料仅保存在本机<span>线下办卡 → 本地录入 → 每日备份</span></div>
    </template>
    <template v-else-if="tab==='reports'"><section class="report-toolbar content-panel"><div><h2>经营月报</h2><p>新增会员按首次开卡开始日期统计；续卡和作废按实际办理时间统计。</p></div><div><el-date-picker v-model="reportMonth" type="month" value-format="YYYY-MM" format="YYYY/MM" :clearable="false" @change="run(loadReport)"/><el-button :icon="Refresh" :loading="reportLoading" @click="run(loadReport)">刷新</el-button><el-button type="primary" :icon="Download" :loading="reportSaving" @click="run(()=>exportPdf('monthly'))">导出月度报表 PDF</el-button></div></section><div v-loading="reportLoading" class="report-content"><template v-if="report"><section class="report-kpis"><div><span>新增会员</span><b>{{report.metrics.newMembers}}</b><small>年卡 {{report.metrics.newYear}} · 月卡 {{report.metrics.newMonth}}</small></div><div><span>续卡会员</span><b>{{report.metrics.renewMembers}}</b><small>共 {{report.metrics.renewCount}} 次续卡</small></div><div><span>未到期续卡</span><b>{{report.metrics.early}}</b><small>提前锁定续费</small></div><div><span>到期后续卡</span><b>{{report.metrics.late+report.metrics.reopened}}</b><small>含作废后重新开卡 {{report.metrics.reopened}} 人</small></div></section><section class="report-grid"><div class="content-panel report-section"><div class="panel-heading"><div><h2>最近 12 个月趋势</h2><p>绿色为新增会员，金色为续卡会员（去重）</p></div></div><div class="trend-chart"><div v-for="item in report.trend" :key="item.month" class="trend-item"><div class="trend-bars"><i class="new" :style="{height:(item.newMembers?Math.max(8,item.newMembers/Math.max(1,...report.trend.flatMap(x=>[x.newMembers,x.renewMembers]))*100):2)+'%'}"></i><i class="renew" :style="{height:(item.renewMembers?Math.max(8,item.renewMembers/Math.max(1,...report.trend.flatMap(x=>[x.newMembers,x.renewMembers]))*100):2)+'%'}"></i></div><b>{{item.newMembers}} / {{item.renewMembers}}</b><span>{{item.month.slice(5)}}月</span></div></div></div><div class="content-panel report-section"><div class="panel-heading"><div><h2>当前会员概况</h2><p>截至 {{formatDateTime(report.generatedAt)}}（北京时间）</p></div></div><dl class="report-overview"><div><dt>全部会员</dt><dd>{{report.current.total}}</dd></div><div><dt>有效会员</dt><dd>{{report.current.active}}</dd></div><div><dt>有效年卡</dt><dd>{{report.current.activeYear}}</dd></div><div><dt>有效月卡</dt><dd>{{report.current.activeMonth}}</dd></div><div><dt>已到期</dt><dd>{{report.current.expired}}</dd></div><div><dt>已作废</dt><dd>{{report.current.voided}}</dd></div></dl></div></section><section class="content-panel report-followup"><div class="panel-heading"><div><h2>需要跟进的会员</h2><p>即将到期 {{report.expiring.length}} 人 · 最近 30 天已到期未续卡 {{report.expired.length}} 人</p></div></div><el-tabs><el-tab-pane :label="`即将到期 ${report.expiring.length}`"><el-table :data="report.expiring" max-height="360"><el-table-column prop="name" label="姓名"/><el-table-column prop="card_number" label="会员号码" min-width="140"/><el-table-column prop="phone" label="手机号" min-width="130"/><el-table-column label="卡种"><template #default="{row}">{{kindLabel(row.card.kind)}}</template></el-table-column><el-table-column label="到期日期"><template #default="{row}">{{formatDate(row.card.end_date)}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="`已到期未续卡 ${report.expired.length}`"><el-table :data="report.expired" max-height="360"><el-table-column prop="name" label="姓名"/><el-table-column prop="card_number" label="会员号码" min-width="140"/><el-table-column prop="phone" label="手机号" min-width="130"/><el-table-column label="到期日期"><template #default="{row}">{{formatDate(row.card.end_date)}}</template></el-table-column><el-table-column prop="expiredDays" label="过期天数"/></el-table></el-tab-pane></el-tabs></section><el-alert v-if="report.unknownFirst" type="warning" :closable="false" :title="`${report.unknownFirst} 位会员缺少首次开卡历史，未计入新增会员统计。`"/></template></div></template>
    <template v-else-if="tab==='imports'"><section class="import-guide"><div v-for="(step,i) in ['下载标准模板','填写并上传资料','核对后确认导入']" :key="step"><span>{{String(i+1).padStart(2,'0')}}</span><b>{{step}}</b><p>{{['保留表头，每行填写一名会员。','系统会检查格式、日期和重复数据。','全部校验通过后，一次性保存。'][i]}}</p></div></section><section class="content-panel"><div class="panel-heading"><div><h2>导入会员档案</h2><p>支持 .xlsx，最大 5 MB，每批最多 2,000 位会员</p></div><el-button :icon="Download" @click="run(()=>download('/admin/imports/template','会员导入模板.xlsx'))">下载模板</el-button></div><div class="drop-area" :class="{busy:importing}"><div class="upload-icon"><el-icon><Upload/></el-icon></div><h3>{{importing?'正在处理工作簿…':'选择填写好的会员表格'}}</h3><p>姓名、手机号、卡种、起止日期为必填项；期限偏离月卡 {{store.monthCardDays}} 天或年卡 {{store.yearCardDays}} 天时，必须填写备注。</p><el-button type="primary" :loading="importing" @click="fileInput?.click()">选择 Excel 文件</el-button><input ref="fileInput" type="file" accept=".xlsx" hidden @change="event=>run(()=>chooseImport(event))"/></div>
      <div v-if="preview" class="import-preview"><el-alert :type="preview.status==='invalid'?'error':'success'" :closable="false" :title="preview.status==='committed'?`已导入 ${preview.count} 位会员，重复提交不会再次导入`:preview.status==='invalid'?`发现 ${preview.errors.length} 处问题，尚未写入任何会员`:`${preview.count} 位会员通过校验，请核对后确认`" show-icon/><div v-if="preview.errors.length" class="error-list"><p v-for="(error,i) in preview.errors" :key="i"><b>{{error.row?'第 '+error.row+' 行':'文件'}}</b>{{error.message}}</p></div><el-table :data="preview.rows" max-height="400" class="preview-table"><el-table-column prop="row" label="行" width="60"/><el-table-column prop="name" label="姓名"/><el-table-column prop="phone" label="手机号"/><el-table-column label="卡种" width="80"><template #default="{row}">{{kindLabel(row.kind)}}</template></el-table-column><el-table-column label="开始日期"><template #default="{row}">{{formatDate(row.startDate)}}</template></el-table-column><el-table-column label="到期日期"><template #default="{row}">{{formatDate(row.endDate)}}</template></el-table-column><el-table-column prop="cardRemark" label="备注"/><el-table-column prop="note" label="档案备注"/></el-table><div class="import-actions"><span>不会覆盖系统中已有的会员资料</span><el-button v-if="preview.status==='ready'" type="primary" :loading="importing" @click="run(confirmImport)">确认导入 {{preview.count}} 位会员</el-button></div></div></section><section class="content-panel history-panel"><h2>近期导入</h2><el-table :data="batches"><el-table-column label="时间"><template #default="{row}">{{formatDateTime(row.created_at)}}</template></el-table-column><el-table-column prop="count" label="会员数"/><el-table-column label="状态"><template #default="{row}"><span class="status-pill" :class="row.status==='committed'?'active':row.status==='invalid'?'voided':'upcoming'">{{{committed:'已导入',ready:'待确认',invalid:'校验未通过'}[row.status as string]}}</span></template></el-table-column></el-table></section></template>
    <template v-else><div class="settings-grid"><section class="content-panel settings-form"><h2>门店与会员卡设置</h2><p class="muted">卡期修改只影响之后的新办和续卡，不会改变已有记录。</p><div class="store-logo-row"><img v-if="store.hasLogo" :src="'/api/store/logo?v='+logoVersion" alt="门店 Logo"/><div v-else class="store-logo-placeholder">↗</div><div><el-button @click="logoInput?.click()">上传门店 Logo</el-button><p>JPEG / PNG，最大 5 MB</p><input ref="logoInput" type="file" accept="image/jpeg,image/png" hidden @change="event=>run(()=>chooseLogo(event))"/></div></div><el-form label-position="top"><el-form-item label="门店名称"><el-input v-model="storeDraft.name" maxlength="50" placeholder="填写你的健身房名称"/></el-form-item><el-form-item label="联系电话"><el-input v-model="storeDraft.phone" maxlength="30" placeholder="例如：13800138000"/></el-form-item><div class="form-grid"><el-form-item label="月卡有效天数"><el-input-number v-model="storeDraft.monthCardDays" :min="1" :max="3650"/></el-form-item><el-form-item label="年卡有效天数"><el-input-number v-model="storeDraft.yearCardDays" :min="1" :max="3650"/></el-form-item></div></el-form><el-button type="primary" :loading="settingsBusy" @click="run(saveSettings)">保存门店与卡期设置</el-button></section><section class="content-panel settings-form"><h2>管理员密码</h2><p class="muted">修改密码后，需要重新登录工作台。</p><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="passwordForm.current" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="passwordForm.next" type="password" show-password autocomplete="new-password" placeholder="至少 8 位，可使用纯数字"/></el-form-item><el-form-item label="再次输入新密码"><el-input v-model="passwordForm.confirm" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><el-button @click="run(changePassword)">更新密码</el-button></section></div>
      <section class="content-panel backup-panel"><div class="panel-heading"><div><h2>Excel自动备份</h2><p>每天保存到本机并通过QQ邮箱发送；授权码只保存在Windows凭据管理器。</p></div><span class="status-pill" :class="backup.automaticStatus==='completed'?'active':backup.automaticStatus==='failed'?'voided':'upcoming'">{{backup.automaticStatusText}}</span></div><div class="backup-form"><el-form label-position="top"><el-form-item label="本地备份目录"><el-input v-model="backupDraft.directory"><template #append><el-button @click="run(chooseBackupDirectory)">选择</el-button></template></el-input></el-form-item><div class="form-grid"><el-form-item label="QQ发件邮箱"><el-input v-model="backupDraft.senderEmail" placeholder="example@qq.com"/></el-form-item><el-form-item label="备份收件邮箱"><el-input v-model="backupDraft.recipientEmail"/></el-form-item><el-form-item label="每天备份时间"><el-time-select v-model="backupDraft.scheduleTime" start="00:00" step="00:30" end="23:30"/></el-form-item><el-form-item label="本地保留份数"><el-input-number v-model="backupDraft.retentionCount" :min="1" :max="365"/></el-form-item></div><div class="smtp-credential-row"><el-form-item class="smtp-credential-field" label="QQ邮箱SMTP授权码"><el-input v-model="backupDraft.smtpCode" type="password" show-password placeholder="留空表示不修改；不是QQ登录密码"/></el-form-item><el-button :loading="backupBusy" @click="run(testBackupEmail)">发送测试邮件</el-button></div></el-form><div class="backup-save-row"><el-button :loading="backupBusy" @click="run(saveBackupSettings)">保存设置</el-button></div><div class="backup-action-row"><span>备份与恢复</span><div class="backup-primary-actions"><el-button type="primary" :loading="backupBusy" @click="run(runBackup)">立即完整备份</el-button><el-button type="warning" plain @click="restoreInput?.click()">从完整备份恢复</el-button><input ref="restoreInput" type="file" accept=".xlsx" hidden @change="event=>run(()=>restoreBackup(event))"/></div></div><div class="backup-action-row backup-utility-row"><span>本地文件</span><div class="backup-utility-actions"><el-button @click="run(openBackupDirectory)">打开备份目录</el-button><el-button @click="run(openOperationLogDirectory)">打开操作日志目录</el-button></div></div><el-alert v-if="backup.latest?.error" type="error" :closable="false" :title="backup.latest.error"/></div></section>
    </template>
    </main><footer class="workspace-footer">JOYFIT · 悦体健身 <span>专注每一位会员的日常</span></footer></div>
  </div>
  <el-drawer v-model="drawer" title="会员详情" size="540px" destroy-on-close><div v-loading="detailLoading" class="detail-body" v-if="selected"><CardPreview :member="selected" :store-name="store.name"/><div class="detail-heading"><div><h2>{{selected.name}}</h2><p>{{selected.phone}} <span>·</span> {{selected.card_number}}</p></div><el-button type="primary" :icon="Plus" @click="renew()">办理续卡</el-button></div><el-tabs v-model="detailTab"><el-tab-pane label="会员卡记录" name="cards"><div v-if="selected.card" class="record-card current-card"><div><span class="kind-badge" :class="selected.card.kind">{{kindLabel(selected.card.kind)}}</span><span class="status-pill member-status" :class="selected.card.status"><i></i>{{statusLabels[selected.card.status]}}</span></div><p>{{formatDate(selected.card.start_date)}} <span>至</span> {{formatDate(selected.card.end_date)}}</p><small v-if="selected.card.void_reason">作废原因：{{selected.card.void_reason}}</small><div v-if="!selected.card.voided_at" class="record-actions"><el-button class="void-card-button" @click="run(voidCard)">作废会员卡</el-button><el-button text :icon="EditPen" @click="renew(selected.card)">修改卡片</el-button></div></div><div class="history-caption">历史记录</div><div v-for="event in selected.cardHistory" :key="event.id" class="record-card history-record"><div class="history-record-title"><b>{{historyTitle(event)}}</b></div><p>{{formatDate(event.start_date)}} <span>至</span> {{formatDate(event.end_date)}}</p><small v-if="event.duration_days" class="history-time">本次采用 {{event.duration_days}} 天 · {{formatDateTime(event.created_at)}}</small><small v-else class="history-time">{{formatDateTime(event.created_at)}}</small><div v-if="event.remark" class="event-remark"><span :class="{collapsed:remarkLong(event.remark)&&!remarkExpanded(event.id)}">备注：{{event.remark}}</span><button v-if="remarkLong(event.remark)" type="button" :aria-expanded="remarkExpanded(event.id)" @click="toggleRemark(event.id)">{{remarkExpanded(event.id)?'收起':'展开全部'}}</button></div><small v-if="event.void_reason">作废原因：{{event.void_reason}}</small></div></el-tab-pane><el-tab-pane label="会员资料" name="profile"><dl class="profile-fields"><dt>姓名</dt><dd>{{selected.name}}</dd><dt>手机号</dt><dd>{{selected.phone}}</dd><dt>会员号码</dt><dd>{{selected.card_number}}</dd><dt>录入日期</dt><dd>{{formatDateTime(selected.created_at)}}</dd><dt>内部备注</dt><dd class="note-text">{{selected.note||'暂无备注'}}</dd></dl><el-button :icon="EditPen" @click="editMember">编辑会员资料</el-button></el-tab-pane></el-tabs></div></el-drawer>
  <el-dialog v-model="memberDialog" :title="editingMember?'编辑会员资料':'录入新会员'" width="560px" :close-on-click-modal="false"><p class="dialog-intro">{{editingMember?'修改手机号不会改变系统生成的会员号码。':'确认会员已在线下签署协议并付款，再录入会员卡信息。会员号码由系统自动生成。'}}</p><el-form label-position="top" @submit.prevent><div class="form-grid"><el-form-item label="姓名 *"><el-input v-model="memberForm.name" placeholder="会员真实姓名" maxlength="50"/></el-form-item><el-form-item label="手机号 *"><el-input v-model="memberForm.phone" placeholder="用于检索和联系会员" maxlength="11"/></el-form-item></div><template v-if="!editingMember"><el-form-item label="会员卡种 *"><el-radio-group v-model="memberForm.kind"><el-radio-button value="year">年卡</el-radio-button><el-radio-button value="month">月卡</el-radio-button></el-radio-group></el-form-item><div class="form-grid"><el-form-item label="开始日期 *"><el-date-picker v-model="memberForm.startDate" type="date" value-format="YYYY-MM-DD" placeholder="选择开始日期"/></el-form-item><el-form-item label="到期日期 *"><el-date-picker v-model="memberForm.endDate" type="date" value-format="YYYY-MM-DD" placeholder="选择到期日期"/></el-form-item></div><el-form-item :label="memberRemarkRequired?'备注 *':'备注（选填）'"><el-input v-model="memberForm.cardRemark" type="textarea" :rows="2" maxlength="500" show-word-limit :placeholder="memberRemarkRequired?`期限偏离月卡 ${store.monthCardDays} 天或年卡 ${store.yearCardDays} 天，请说明原因`:'记录本次办理的补充信息'"/></el-form-item></template><el-form-item label="会员档案备注"><el-input v-model="memberForm.note" type="textarea" :rows="3" maxlength="2000" placeholder="补充长期需要留意的信息"/></el-form-item></el-form><template #footer><el-button @click="memberDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="run(saveMember)">{{editingMember?'保存修改':'保存并开卡'}}</el-button></template></el-dialog>
  <el-dialog v-model="cardDialog" :title="cardEditing?'修改会员卡':'办理续卡'" width="480px" :close-on-click-modal="false"><p class="dialog-intro">{{cardEditing?'修改卡种或日期后会保留会员卡历史。':renewalUnexpired?'续卡将从当前到期日继续延长，不会产生空档。':'会员卡已到期或作废，默认从今天重新开始。'}}</p><el-form label-position="top"><el-form-item :label="cardEditing?'卡种':'续卡类型'"><el-radio-group v-model="cardForm.kind"><el-radio-button value="year">年卡</el-radio-button><el-radio-button value="month">月卡</el-radio-button></el-radio-group></el-form-item><el-alert v-if="!cardEditing&&effectiveRenewalKind!==cardForm.kind" type="info" :closable="false" :title="`当前为年卡，本次续月卡将延长 ${store.monthCardDays} 天，卡种仍显示年卡。`"/><el-form-item label="开始日期"><el-date-picker v-model="cardForm.startDate" class="card-date-control" type="date" value-format="YYYY-MM-DD" :disabled="!cardEditing&&renewalUnexpired"/></el-form-item><el-form-item v-if="!cardEditing&&renewalUnexpired" label="原到期日期"><el-input :model-value="formatDate(renewalOriginalEnd)" class="card-date-control" disabled/></el-form-item><el-form-item :label="!cardEditing&&renewalUnexpired?'新到期日期':'到期日期'"><el-date-picker v-model="cardForm.endDate" class="card-date-control" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item :label="cardRemarkRequired?'备注 *':'备注（选填）'"><el-input v-model="cardForm.remark" type="textarea" :rows="3" maxlength="500" show-word-limit :placeholder="cardRemarkRequired?'日期偏离系统默认期限，请说明原因':'记录本次办理的补充信息'"/></el-form-item></el-form><template #footer><el-button @click="cardDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="run(saveCard)">{{cardEditing?'保存修改':'确认续卡'}}</el-button></template></el-dialog>
</template>
